/** Teaches a model to write a molen/film@1 document. */
export const MOLEN_FILM_PRIMER: string = "### Writing a Molen film (molen/film@1)\n\nA film is one JSON document. You choose the look, the set, the cast, what they do and when, and the shots. Molen works out positions, walking, framing and light. Ground positions are `[x, z]` in meters: x is left to right, z is toward the camera. Times are in seconds.\n\n```json\n{ \"format\": \"molen/film@1\", \"name\": \"Title\", \"look\": \"noon\", \"length\": 8,\n  \"set\": { \"ground\": \"grass\", \"props\": [] },\n  \"marks\": { \"spot\": [0, 0] },\n  \"cast\": [], \"beats\": [], \"shots\": [] }\n```\n\n- `look`: morning, noon, evening, night or overcast. Every look is lit well enough to see.\n- `length` (optional): seconds. Add `\"loop\": true` to repeat the film forever.\n- `set.ground`: grass, plaza, sand, street, wood, snow, dirt or water.\n- `set.props`: things in the scene, each `{ \"id\": \"unique-name\", \"shape\": ..., \"at\": place, \"on\": \"other-prop-id\", \"size\": [w, h, d], \"color\": \"#rrggbb\" }`. Only `id` and `shape` are required.\n  Shapes: tree, bench, lamp (gives light), table, tower, hill, flag, fountain, house, stall, fence, car, rock, ball, box, sphere, cylinder. Each shape has a sensible size; give `size` only to change it.\n  `on` stands a prop on top of another one: a ball on a table, a tower on a hill, a flag on a tower.\n- `marks`: named spots, so beats and cast can say `\"at\": \"door\"` instead of numbers.\n- A place is a mark name, the id of a prop or cast member (next to it), or `[x, z]`.\n- `cast`: people and animals, each `{ \"id\": \"name\", \"preset\": ..., \"at\": place, \"colors\": { \"top\": \"#rrggbb\", \"bottom\": \"#rrggbb\" } }`.\n  Presets: human.adult, human.child, human.elder, dog, cat, horse, deer, cow, sheep.\n- `beats`: what happens, each `{ \"at\": seconds, \"who\": id, \"do\": ..., \"target\": place, \"seconds\": duration }`.\n  - `walk-to` / `run-to` a place. Walking to a person or a prop stops a step short and faces them.\n  - `move-to` / `roll-to`: a prop slides or rolls to a place.\n  - `sit` (on the ground, or `\"target\"` a bench), `stand`, `look-at` a target.\n  `seconds` is optional; without it Molen uses a natural speed.\n- `shots`: the camera, each `{ \"at\": seconds, \"kind\": ..., \"on\": id or [ids] }`. A new shot is a cut.\n  Kinds: wide, establishing, medium, close, push-in, pull-out, orbit, follow, over-the-shoulder (`on`: [from-whom, at-whom]).\n  Molen frames every shot on its subjects; you never place the camera.\n- `captions` (optional): words on screen, each `{ \"at\": seconds, \"seconds\": 3, \"text\": \"...\" }`.\n\nExample: a farmer leads a horse to the barn while a cat watches.\n\n```json\n{ \"format\": \"molen/film@1\", \"name\": \"To the barn\", \"look\": \"morning\",\n  \"set\": { \"ground\": \"dirt\", \"props\": [\n    { \"id\": \"barn\", \"shape\": \"house\", \"at\": [6, -6], \"color\": \"#9c3b2a\" },\n    { \"id\": \"fence\", \"shape\": \"fence\", \"at\": [-4, -3] },\n    { \"id\": \"post\", \"shape\": \"box\", \"at\": \"fence\", \"size\": [0.3, 1.2, 0.3] } ] },\n  \"marks\": { \"gate\": [-6, 3] },\n  \"cast\": [\n    { \"id\": \"farmer\", \"preset\": \"human.elder\", \"colors\": { \"top\": \"#6b8e23\" }, \"at\": \"gate\" },\n    { \"id\": \"horse\", \"preset\": \"horse\", \"at\": [-8, 4] },\n    { \"id\": \"cat\", \"preset\": \"cat\", \"at\": \"post\" } ],\n  \"beats\": [\n    { \"at\": 0, \"who\": \"farmer\", \"do\": \"walk-to\", \"target\": \"barn\" },\n    { \"at\": 0.5, \"who\": \"horse\", \"do\": \"walk-to\", \"target\": \"farmer\" },\n    { \"at\": 0, \"who\": \"cat\", \"do\": \"look-at\", \"target\": \"horse\" },\n    { \"at\": 9, \"who\": \"farmer\", \"do\": \"look-at\", \"target\": \"horse\" } ],\n  \"shots\": [\n    { \"at\": 0, \"kind\": \"establishing\", \"on\": [\"farmer\", \"horse\", \"barn\"] },\n    { \"at\": 4, \"kind\": \"follow\", \"on\": \"horse\" },\n    { \"at\": 9, \"kind\": \"close\", \"on\": \"farmer\" } ],\n  \"captions\": [ { \"at\": 0.5, \"seconds\": 3, \"text\": \"Early, before the rain.\" } ] }\n```\n\nReply with the JSON only, in ```json fences.\n";

/** Teaches a model to write a molen/game@1 document. */
export const MOLEN_GAME_PRIMER: string = "### Writing a Molen game (molen/game@1)\n\nA game is one JSON document. You choose the pieces and how many of each, pick a layout, and say how to win and lose. Molen draws a level the player can finish and builds the 3D scene, the controls (arrow keys or WASD, Space to jump, R to play again), the camera, the score and lives display, and the rules for each kind of piece.\n\n```json\n{ \"format\": \"molen/game@1\", \"name\": \"Title\", \"kind\": \"top-down\", \"layout\": \"garden\",\n  \"pieces\": { \"P\": { \"role\": \"player\" }, \"o\": { \"role\": \"pickup\", \"count\": 3 } },\n  \"win\": { \"collect\": \"all\" }, \"lose\": { \"lives\": 3 } }\n```\n\n- `kind`: \"top-down\" (seen from above) or \"platformer\" (seen from the side; the player runs left to right, jumps and falls).\n- `layout`: the level Molen draws. Top-down: \"garden\" (open ground with a few hedges), \"maze\" (narrow corridors), \"arena\" (an open walled square). Platformer: \"level\" (ground with gaps to jump over).\n  To adjust it, give an object instead: `{ \"archetype\": \"maze\", \"size\": \"large\", \"loops\": \"many\", \"corridors\": \"wide\", \"seed\": \"b\" }`. Every field but `archetype` is optional:\n  - garden: `hedges` few, some or many\n  - maze: `loops` none, few or many; `corridors` narrow or wide\n  - arena: `pillars` none, few or many\n  - level: `gaps` few, some or many; `hills` flat, rolling or steep; `ledges` none, some or many\n  - any: `size` small, medium, large or `[columns, rows]`; `seed` any word, for a different level with the same choices.\n- `size` (optional): \"small\", \"medium\" (the default) or \"large\".\n- `look`: morning, noon, evening, night or overcast.\n- `pieces`: one character each. Each piece has a `role`:\n  - `player` (there is always exactly one),\n  - `pickup` (collected by touching it; `points` optional), `goal` (touching it can win),\n  - `key` (touching it opens every `door`), `door` (Molen puts it in front of the goal, and the key somewhere else),\n  - `hazard` (touching it costs a life; the player starts again where they began; in a level, falling into a gap does too),\n  - `wall` (only to choose the walls' color; the layout makes the walls).\n  `count`: how many Molen places (default 1). Optional: `figure` (human.adult, human.child, human.elder, dog, cat, horse, deer, cow, sheep) or `shape` (box, sphere, cylinder), `color` \"#rrggbb\", `speed` (meters per second).\n  Hazards can `move`: \"still\" (default), \"patrol\" (back and forth), \"chase\" (follows the player) or \"wander\".\n- `win`: any of `\"collect\": \"all\"` (every pickup), `\"reach\": \"goal\"`, `\"survive\": seconds`. With both collect and reach, the goal counts only after every pickup is taken.\n- `lose`: `{ \"lives\": n }`.\n- `spawn` (optional): `[ { \"piece\": \"e\", \"every\": seconds, \"max\": n } ]` keeps adding that piece at the edges.\n- `text` (optional): `{ \"title\": \"...\", \"win\": \"...\", \"lose\": \"...\" }`.\n- `map` (optional, instead of `layout`): draw the level yourself as rows of characters, \".\" for empty floor.\n\nExample: Lantern Run. Reach the lantern while two moths wander the dark garden.\n\n```json\n{ \"format\": \"molen/game@1\", \"name\": \"Lantern Run\", \"kind\": \"top-down\", \"layout\": \"garden\", \"size\": \"small\", \"look\": \"night\",\n  \"pieces\": {\n    \"P\": { \"role\": \"player\", \"figure\": \"human.child\", \"speed\": 5 },\n    \"#\": { \"role\": \"wall\", \"color\": \"#4a4e69\" },\n    \"m\": { \"role\": \"hazard\", \"shape\": \"sphere\", \"color\": \"#c9ada7\", \"move\": \"wander\", \"speed\": 2, \"count\": 2 },\n    \"L\": { \"role\": \"goal\", \"color\": \"#ffd166\" } },\n  \"win\": { \"reach\": \"goal\" }, \"lose\": { \"lives\": 2 },\n  \"text\": { \"title\": \"Lantern Run\", \"win\": \"You found the light.\", \"lose\": \"The moths got you.\" } }\n```\n\nReply with the JSON only, in ```json fences.\n";

/** Teaches a model to write a data-only molen/scene@3 by hand. */
export const MOLEN_SCENE_PRIMER: string = "### Writing a Molen scene (molen/scene@3)\n\nA Molen scene is one JSON document. Y is up, units are meters, and time is counted in ticks: with \"tickRate\": 30, 30 ticks are one second.\n\n```json\n{ \"format\": \"molen/scene@3\", \"name\": \"short-name\", \"seed\": \"any-text\", \"tickRate\": 30,\n  \"entities\": [], \"camera\": { \"mode\": \"fixed\", \"position\": [0, 4, 12] } }\n```\n\nEach entity is `{ \"id\": \"unique-id\", \"components\": { ... } }`. Use only these components:\n\n- `transform`: `{ \"pos\": [x, y, z] }`, the center of the object. Leave out rotation.\n- `renderable` for a shape: `{ \"kind\": \"primitive\", \"ref\": \"box\" | \"sphere\" | \"cylinder\", \"materialRef\": \"palette:#rrggbb\", \"primitive\": { \"size\": [x, y, z] } }`. Size is in meters: box = width, height, depth; sphere = diameter in x; cylinder = diameter in x, height in y. A shape is centered on pos, so a box 2 m tall standing on the ground has pos y = 1. A floor is a thin box: size [40, 0.1, 40] at pos y = -0.05.\n- `renderable` for a person or animal: `{ \"kind\": \"figure\" }` together with\n  `figure`: `{ \"preset\": \"human.adult\" | \"human.child\" | \"human.elder\" | \"dog\" | \"cat\" | \"horse\" | \"deer\" | \"cow\" | \"sheep\", \"palette\": { \"top\": \"#rrggbb\", \"bottom\": \"#rrggbb\" } }`.\n  A figure stands with its feet at pos (y = 0 on the ground). It walks or runs, and turns to face where it goes, on its own whenever it moves.\n- `figureIntent` (optional, with a figure): `{ \"mode\": \"sit\" }`, or `{ \"lookAt\": { \"entity\": \"other-id\" } }` (it looks at their face).\n- `path`, walking somewhere: `{ \"points\": [[x, y, z]], \"speed\": 1.3, \"delay\": 30 }`. It starts from where the entity stands, after `delay` ticks; `speed` is meters per second. Use `\"ticks\": 90` instead of `speed` to arrive in that time.\n- `cues`, things that happen later, on one entity with id \"director\": `{ \"cues\": [ { \"tick\": 150, \"do\": [ { \"figure\": { \"target\": \"#ana\", \"mode\": \"sit\" } } ] } ] }`. An action can also be `{ \"path\": { \"target\": \"#ben\", \"points\": [[2, 0, 1]], \"speed\": 1.3 } }` or `{ \"figure\": { \"target\": \"#ben\", \"lookAt\": \"#ana\" } }`.\n- `light`: `{ \"type\": \"point\", \"color\": \"#ffdca8\", \"intensity\": 2, \"range\": 12 }`.\n- `environment`, on one entity with id \"env\" and no other components: `{ \"preset\": \"evening\", \"shadows\": \"medium\" }`. Presets: morning, noon, evening, night, overcast; every one is lit well enough to see.\n\nScene camera: `{ \"mode\": \"fixed\", \"position\": [x, y, z], \"lookAt\": [x, y, z] }`, or to follow an entity `{ \"mode\": \"follow\", \"entity\": \"id\", \"offset\": [0, 3, 8], \"lookOffset\": [0, 1, 0] }`.\n\nA camera move goes in the same document as `cameraTrack`:\n\n```json\n{ \"cameraTrack\": { \"easing\": \"smooth\", \"keyframes\": [\n  { \"tick\": 0, \"position\": [-6, 6, 16], \"lookAt\": [-4, 1, 3] },\n  { \"tick\": 150, \"position\": [2, 2.2, 8], \"lookAt\": [0, 1.4, 3], \"cut\": true } ] } }\n```\n\n`\"cut\": true` jumps to that keyframe instead of moving to it.\n\nExample scene: a person walks to a fountain where a friend waits, then sits down.\n\n```json\n{ \"format\": \"molen/scene@3\", \"name\": \"plaza\", \"seed\": \"plaza-1\", \"tickRate\": 30,\n  \"entities\": [\n    { \"id\": \"env\", \"components\": { \"environment\": { \"preset\": \"noon\", \"shadows\": \"medium\" } } },\n    { \"id\": \"ground\", \"components\": { \"transform\": { \"pos\": [0, -0.05, 0] }, \"renderable\": { \"kind\": \"primitive\", \"ref\": \"box\", \"materialRef\": \"palette:#b9b1a3\", \"primitive\": { \"size\": [40, 0.1, 40] } } } },\n    { \"id\": \"fountain\", \"components\": { \"transform\": { \"pos\": [0, 0.4, 0] }, \"renderable\": { \"kind\": \"primitive\", \"ref\": \"cylinder\", \"materialRef\": \"palette:#8a8f99\", \"primitive\": { \"size\": [3, 0.8, 3] } } } },\n    { \"id\": \"ana\", \"components\": { \"transform\": { \"pos\": [-8, 0, 3] }, \"renderable\": { \"kind\": \"figure\" }, \"figure\": { \"preset\": \"human.adult\", \"palette\": { \"top\": \"#c0392b\", \"bottom\": \"#2f2f38\" } }, \"path\": { \"points\": [[-1.2, 0, 3]], \"speed\": 1.3 } } },\n    { \"id\": \"ben\", \"components\": { \"transform\": { \"pos\": [1, 0, 3] }, \"renderable\": { \"kind\": \"figure\" }, \"figure\": { \"preset\": \"human.adult\", \"palette\": { \"top\": \"#2e86de\", \"bottom\": \"#3d3d3d\" } }, \"figureIntent\": { \"lookAt\": { \"entity\": \"ana\" } } } },\n    { \"id\": \"director\", \"components\": { \"cues\": { \"cues\": [ { \"tick\": 210, \"do\": [ { \"figure\": { \"target\": \"#ana\", \"mode\": \"sit\" } } ] } ] } } }\n  ],\n  \"camera\": { \"mode\": \"fixed\", \"position\": [0, 4, 14], \"lookAt\": [0, 1, 2] } }\n```\n\nReply with the JSON only, in ```json fences.\n";
